{
  "cvars": {
    "ivs": [
      {
        "description": "Student-teacher ratio (number of students per teacher). Independent variable. A lower value indicates fewer students per teacher (smaller class size). In the regression a negative coefficient on this variable would indicate that lower student-teacher ratios are associated with higher academic performance.",
        "columns": [
          "StudentTeacherRatio"
        ]
      }
    ],
    "dv": {
      "description": "Average academic performance (average of 5th-grade reading and math Stanford-9 scores). Higher values indicate better academic performance.",
      "columns": [
        "AvgScore"
      ]
    },
    "controls": [
      {
        "description": "Expenditure per student (district-level spending per pupil). Controls for resource intensity.",
        "is_moderator": false,
        "moderator_on": "",
        "columns": [
          "expenditure"
        ]
      },
      {
        "description": "District average income (in thousands USD). Controls for socioeconomic status.",
        "is_moderator": false,
        "moderator_on": "",
        "columns": [
          "income"
        ]
      },
      {
        "description": "Percent qualifying for CalWorks (income assistance). Proxy for student poverty.",
        "is_moderator": false,
        "moderator_on": "",
        "columns": [
          "calworks"
        ]
      },
      {
        "description": "Percent qualifying for reduced-price lunch. Proxy for student poverty.",
        "is_moderator": false,
        "moderator_on": "",
        "columns": [
          "lunch"
        ]
      },
      {
        "description": "Percent of English learners. Controls for language-related performance differences.",
        "is_moderator": false,
        "moderator_on": "",
        "columns": [
          "english"
        ]
      },
      {
        "description": "Computers per student (computer count divided by total students). Controls for technological resources per pupil.",
        "is_moderator": false,
        "moderator_on": "",
        "columns": [
          "ComputersPerStudent"
        ]
      },
      {
        "description": "District size (log of students). Controls for scale effects of district size.",
        "is_moderator": false,
        "moderator_on": "",
        "columns": [
          "LogStudents"
        ]
      },
      {
        "description": "Grade-span indicator (KK-06 vs KK-08). Categorical control capturing structural differences in districts.",
        "is_moderator": false,
        "moderator_on": "",
        "columns": [
          "grades"
        ]
      },
      {
        "description": "County identifier (used as categorical fixed effect to absorb unobserved county-level heterogeneity).",
        "is_moderator": false,
        "moderator_on": "",
        "columns": [
          "county"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"\n    Transform the raw district-level dataframe to produce the final modeling dataframe.\n\n    Produces the following new columns used by the model:\n      - AvgScore: mean of 'read' and 'math'\n      - StudentTeacherRatio: students / teachers (winsorized at 1st/99th percentiles)\n      - ComputersPerStudent: computer / students\n      - LogStudents: natural log of students\n\n    Drops rows with missing or invalid values required for modeling.\n    \"\"\"\n    df = df.copy()\n\n    # Ensure numeric columns are numeric\n    numeric_cols = ['students', 'teachers', 'read', 'math', 'computer', 'expenditure', 'income', 'calworks', 'lunch', 'english']\n    for col in numeric_cols:\n        if col in df.columns:\n            df[col] = pd.to_numeric(df[col], errors='coerce')\n\n    # Drop rows missing the essential outcome or denominator for ratio\n    df = df.dropna(subset=['students', 'teachers', 'read', 'math'])\n\n    # Remove invalid teacher counts (must be > 0 for ratio)\n    df = df[df['teachers'] > 0]\n\n    # Dependent variable: average of reading and math\n    df['AvgScore'] = df[['read', 'math']].mean(axis=1)\n\n    # Independent variable: student-teacher ratio (students per teacher)\n    df['StudentTeacherRatio'] = df['students'] / df['teachers']\n\n    # Winsorize the ratio to reduce influence of extreme outliers (1st/99th percentiles)\n    if not df['StudentTeacherRatio'].isna().all():\n        low = df['StudentTeacherRatio'].quantile(0.01)\n        high = df['StudentTeacherRatio'].quantile(0.99)\n        df['StudentTeacherRatio'] = df['StudentTeacherRatio'].clip(lower=low, upper=high)\n\n    # Computer resources normalized by student body size\n    df['ComputersPerStudent'] = df['computer'] / df['students']\n\n    # Log students to capture scale nonlinearity\n    # Guard against nonpositive students (already filtered), but be safe\n    df['LogStudents'] = np.log(df['students'].replace(0, np.nan))\n\n    # Ensure categorical controls exist and have no missing values for modeling\n    # We'll keep 'grades' and 'county' as categorical variables in the model (C(...))\n    if 'grades' in df.columns:\n        df['grades'] = df['grades'].astype('category')\n    if 'county' in df.columns:\n        df['county'] = df['county'].astype('category')\n\n    # Drop rows with missing values in controls used in the model\n    control_cols = ['expenditure', 'income', 'calworks', 'lunch', 'english', 'ComputersPerStudent', 'LogStudents', 'grades', 'county']\n    # Some of these (grades, county) may be non-numeric; dropna will handle them\n    df = df.dropna(subset=[c for c in control_cols if c in df.columns])\n\n    # Reset index for cleanliness\n    df = df.reset_index(drop=True)\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame):\n    \"\"\"\n    Runs an OLS regression testing the association between student-teacher ratio and average test scores,\n    controlling for district resources and demographics. Returns the fitted statsmodels results instance.\n\n    Model specification:\n      AvgScore ~ StudentTeacherRatio + I(StudentTeacherRatio**2) + expenditure + income + calworks + lunch + english\n                 + ComputersPerStudent + LogStudents + C(grades) + C(county)\n\n    The quadratic term allows for nonlinearity (diminishing returns). County and grades are included as categorical\n    fixed effects using C(...). Robust (HC3) standard errors are requested to mitigate heteroskedasticity.\n    \"\"\"\n    import statsmodels.formula.api as smf\n\n    # Copy to avoid mutating caller's dataframe\n    data = df.copy()\n\n    # Formula including a quadratic term for possible nonlinearity and categorical fixed effects\n    formula = (\n        'AvgScore ~ StudentTeacherRatio + I(StudentTeacherRatio**2) '\n        '+ expenditure + income + calworks + lunch + english '\n        '+ ComputersPerStudent + LogStudents + C(grades) + C(county)'\n    )\n\n    # Fit OLS with robust standard errors (HC3)\n    model_res = smf.ols(formula, data=data).fit(cov_type='HC3')\n\n    # Print a concise summary for quick inspection (caller can use the returned object for detailed analysis)\n    print(model_res.summary())\n\n    # Return the fitted model results object for downstream inspection (coefficients, p-values, CIs, residuals, etc.)\n    return model_res\n"
}

